CREATE TABLE field_projects (field_project_id TEXT PRIMARY KEY, procurement_id TEXT NOT NULL, owner_id TEXT NOT NULL, owner_display_name TEXT NOT NULL, project_name TEXT NOT NULL, project_manager_id TEXT NOT NULL, project_manager_display_name TEXT NOT NULL, contract_start_date TEXT NOT NULL, contract_end_date TEXT, project_status TEXT NOT NULL CHECK (project_status IN ('active','completed','on_hold','cancelled')), created_at TEXT NOT NULL);

CREATE TABLE daily_reports (daily_report_id TEXT PRIMARY KEY, field_project_id TEXT NOT NULL, report_date TEXT NOT NULL, report_status TEXT NOT NULL CHECK (report_status IN ('draft','posted','weather_shutdown','voided')), inspector_id TEXT NOT NULL, weather_summary TEXT, work_summary TEXT, submitted_at TEXT, void_reason TEXT, FOREIGN KEY (field_project_id) REFERENCES field_projects(field_project_id));

CREATE TABLE installed_quantity_entries (quantity_entry_id TEXT PRIMARY KEY, daily_report_id TEXT NOT NULL, canonical_sov_item_id TEXT NOT NULL, installed_quantity_milliunits INTEGER NOT NULL CHECK (installed_quantity_milliunits >= 0), accepted_flag INTEGER NOT NULL CHECK (accepted_flag IN (0,1)), measurement_method TEXT NOT NULL CHECK (measurement_method IN ('survey','ticket','field_measure','estimate')), entry_note TEXT, recorded_at TEXT NOT NULL, FOREIGN KEY (daily_report_id) REFERENCES daily_reports(daily_report_id));

CREATE TABLE progress_assessments (assessment_id TEXT PRIMARY KEY, field_project_id TEXT NOT NULL, application_id TEXT NOT NULL, canonical_sov_item_id TEXT NOT NULL, assessment_source TEXT NOT NULL CHECK (assessment_source IN ('contractor','city')), percent_complete_bp INTEGER NOT NULL CHECK (percent_complete_bp BETWEEN 0 AND 10000), target_quantity_milliunits INTEGER NOT NULL CHECK (target_quantity_milliunits > 0), assessment_date TEXT NOT NULL, version_no INTEGER NOT NULL CHECK (version_no > 0), is_current INTEGER NOT NULL CHECK (is_current IN (0,1)), assessor_id TEXT NOT NULL, rationale TEXT, created_at TEXT NOT NULL, FOREIGN KEY (field_project_id) REFERENCES field_projects(field_project_id));

CREATE TABLE field_disputes (dispute_id TEXT PRIMARY KEY, assessment_id TEXT NOT NULL, daily_report_id TEXT NOT NULL, reason_code TEXT NOT NULL CHECK (reason_code IN ('unsupported_quantity','percent_overstatement','duplicate_sync','scope_mismatch','measurement_pending')), resolution_status TEXT NOT NULL CHECK (resolution_status IN ('open','under_review','resolved','withdrawn')), opened_at TEXT NOT NULL, opened_by_id TEXT NOT NULL, resolution_note TEXT, resolved_at TEXT, resolved_by_id TEXT, FOREIGN KEY (assessment_id) REFERENCES progress_assessments(assessment_id), FOREIGN KEY (daily_report_id) REFERENCES daily_reports(daily_report_id));